import{_ as p,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易义海撮要卷十","description":"周易义海撮要 - 周易义海撮要卷十","frontmatter":{"title":"周易义海撮要卷十","description":"周易义海撮要 - 周易义海撮要卷十"},"headers":[],"relativePath":"zh/classics/yihai-cuoyao/011.md","filePath":"zh/classics/yihai-cuoyao/011.md"}'),i={name:"zh/classics/yihai-cuoyao/011.md"};function o(c,a,r,_,n,l){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="周易义海撮要卷十" tabindex="-1">周易义海撮要卷十 <a class="header-anchor" href="#周易义海撮要卷十" aria-label="Permalink to “周易义海撮要卷十”">​</a></h1><p>钦定四库全书</p><p>宗李衡撰。</p><p>有天地，然后万物生焉。盈天地之间者唯万物，故受之以屯。屯者，盈也。屯者，物之始生也。物生必蒙，故受之以蒙。蒙者，蒙也，物之稚也。物稚不可不养也，故受之以需。需者，饮食之道也。饮食必有讼，故受之以讼。讼必有众起，故受之以师，师者，众也。众必有所比，故受之以比。比者，比也。比必有所畜，故受之以小畜。物畜然后有礼，故受之以履。</p><p>屯则塞，塞则盈，此以云雷言也。需非饮食也，饮食之道也。万物之于天，则以雨为需。人之于君，则以饮食为需。两相比者，情也，而义不足以畜，则情胜义而不可久，故比必有所畜，而所以止之也。物畜则万物盛多，而礼所由兴也。 龚</p><p>履而泰然后安，故受之以泰。泰者，通也。物不可以终通，故受之以否。物不可以终否，故受之以同人。与人同者，物必归焉，故受之以大有。有大者不可以盈，故受之以谦。有大而能谦必豫，故受之以豫。豫必有随，故受之以随。以喜随人者必有事，故受之以蛊。蛊者，事也。有事而后可大，故受之以临。临者，大也。物大然后可观，故受之以观。</p><p>否则思通，人人同志，故可出门同人，不谋而合。顺以动者，众之所随。可大之业，由事而生。 注：能行礼者，其身必安，故以「泰」次履。大有天下之众，又能谦顺，则人必悦豫而随之，故以「豫」次「谦」。以喜随人，久而已极，必败成事，故「蛊」次「随」。事既久败，必须有才德之人以临治之，故以「临」次蛊。临人之道，必在中正，中正必有可观，故「观」次「临」。 胡：「以喜随人」者，溺于燕安，故至于蛊，蛊则有事。 坡：以喜随人者必有事，此无思无虑之圣人所以迫而后动，不得已而后起也。豫所谓喜也。 龚：圣人顺动能谦，为物所说，所以为豫。人既说豫，自然随之，则谦顺在君，说豫在人。 孔：</p><p>可观而后有所合，故受之以噬嗑。嗑者，合也。物不可以苟合而已，故受之以贲。贲者，饰也。致饰然后亨则尽矣，故受之以剥。剥者，剥也。物不可以终尽，剥穷上反下，故受之以复。复则不妄矣，故受之以无妄。无妄然后可畜，故受之以大畜。物畜然后可养，故受之以颐。颐者，养也。不养则不可动，故受之以大过。物不可以终过，故受之以坎。坎者，陷也。陷必有所丽，故受之以离。离者，丽也。可观则万方合会，相合则须饰以修外，极饰则实丧，不养则不可动，养过则厚，过而不已则陷没。物穷则变，极陷则反所丽也。 注：君臣、父子、夫妇、朋友之际，所谓合也。直情而行之谓之苟，礼以饰情谓之贲。苟则易合，易合则相渎，渎则易离。贲则难合，难合则相敬，敬则久成。饰极则不胜而实衰，故剥 坡 可观而后有所合，犹曰「不成章不达」也。贲者，饰也。诗、书之光，礼乐之容，车服文章，莫非贲也。致饰然后亨则尽矣，其周公、成王之时乎？礼仪三百，威仪三千，不可加也，有剥而已，譬之「日中则昃」也。故诗序假乐之后有戒焉。阳上而阴下，理之正也。自姤而上，则失正矣，故剥穷上反下而后复，复则阴阳各得其正而不妄，若老子所谓「归根曰静，静曰复命，复命曰常」之时也。无妄者，天之命也，万物听焉。故有无妄然后可畜。在人君则取人以身之谓也。不养则不可动，虽形体亦然，况欲有为乎？故上九由颐，然后「利涉大川」也。小者之过，过其分而已，未及陷也。大者而过，则为已极矣，故过则陷。陷必有所丽，不必物也，虽性亦如之。唯能解脱者，无所丽也。 龚</p><p>有天地，然后有万物，有万物，然后有男女，有男女，然后有夫妇，有夫妇，然后有父子，有父子，然后有君臣，有君臣，然后有上下，有上下，然后礼义有所错。夫妇之道，不可以不久也，故受之以恒。恒者，久也。物不可以久居其所，故受之以遁。遁者，退也。物不可以终遁，故受之以大壮。物不可以终壮，故受之以晋。晋者，进也。进必有所伤，故受之以明夷。夷者，伤也。伤于外者必反于家，故受之以家人。家道穷必乖，故受之以睽。睽者，乖也。乖必有难，故受之以蹇。蹇者，难也。物不可以终难，故受之以解。解者，缓也。缓必有所失，故受之以损。损而不已必益，故受之以益。</p><p>物之所居，不可以恒，宜与时升降。遁：君子以远小人。遁而后亨，何可终邪？则小人遂陵，君子日消也。大壮则阳盛阴消，君子道胜。晋，以柔而进也。家人之义，惟严与敬。礼胜则离。家人尚严，其敝必乖。 注：遁而退处，必须以刚壮之道出其所处。既动而出，必须进，进而不已，人所不与，必有所伤。治家之道，失严正必乖。解人之难，必有所损，损而不已，必须益之。 胡。 人穷则反本，疾痛则必呼父母，故伤则反于家。 坡。 感莫如少，久莫如长，不可久而居其所者，物之变也。遁者，求远小人而已。洁身不仕，则废君臣之义。以天时言之，成功者退；以人道言之，大化有四。故「不可以终壮」。「明出为晋」，则晋者日也，而进者人也。「明入为夷」，则夷者日也，而伤者人也。以人属者，迫穷祸患害相弃；以天属者，迫穷祸患相收。故「伤于外者，必反于家」。家人之道，以严则不穷，以和则必乖。损而不已则虚，故必益 龚。</p><p>益而不已必决，故受之以夬。夬者，决也。决必有所遇，故受之以姤。姤者，遇也。物相遇而后聚，故受之以萃。萃者，聚也。聚而上者谓之升，故受之以升。升而不已必困，故受之以困。困乎上者必反下，故受之以井。井道不可不革，故受之以革。革物者莫若鼎，故受之以鼎。主器者莫若长子，故受之以震。震者，动也。物不可以终动，止之，故受之以艮。艮者，止也。物不可以终止，故受之以渐。渐者，进也。进必有所归，故受之以「归妹」。</p><p>益而不已则盈，故必决。以正决邪，必有所遇。井久则浊秽，宜革易其故。既已去，故宜制器立法以治新。鼎所以和齐生物，成新之器也，故取象焉。 注：君子既有所遇，则万物莫不聚萃。萃之于上，必须升进，升而不已，其道必困。困之既久，必反于下。井道既得其所，不可不革治之。革之必得其道，有鼎新之义焉。物既鼎新，主之者莫若长子。物不可以终动，动必有所止。止物必有渐，渐必有所归。 胡 遇者，小人不足以间君子也。传曰：「跃于龠，合于合，登于升。」故聚而上者为升。鼎者，器也，国家之所宝，故主器者莫若长子。 龚</p><p>得其所归者必大，故受之以丰。丰者，大也。穷大者必失其居，故受之以旅。旅而无所容，故受之以巽。巽者，入也。入而后说之，故受之以兑。兑者，说也。说而后散之，故受之以涣。涣者，离也。物不可以终离，故受之以节。节而信之，故受之以中孚。有其信者必行之，故受之以小过。有过物者必济，故受之以既济。物不可穷也，故受之以未济终焉。</p><p>旅而无所容，以巽故得入。说不可偏系，故宜散。涣者，发散而无所壅滞，则殊趣各肆，不反而乖离。大事有节，则物之所同守而不散。既有节，则宜信以守之。守其信者，失贞而不谅之道，而以信为过，故曰小过也。「行过乎恭，礼过乎俭，可以矫世厉俗，有所济也。有为而能济者，以己穷物者也。物穷则乖，功极则乱，其可济乎？」 注：穷大者必失其居。 龚。 周易义海撮要卷十、</p>',14)])])}const m=p(i,[["render",o]]);export{h as __pageData,m as default};
